import Darwin
import Engine
import Foundation
import Tokenizer

// Resident daemon: keeps the model mapped, pipelines compiled and the system-prompt KV cached, and
// answers `ill` requests over a Unix socket. Protocol: client sends 4 x UInt32 (magic "ILQ1",
// max tokens, system length, prompt length) + system bytes + prompt bytes; the server streams the
// generated bytes and closes the connection.

func socketPath() -> String {
    if let s = ProcessInfo.processInfo.environment["INSTANTLLM_SOCKET"], !s.isEmpty { return s }
    let tmp = ProcessInfo.processInfo.environment["TMPDIR"].flatMap { $0.isEmpty ? nil : $0 } ?? "/tmp"
    return (tmp.hasSuffix("/") ? String(tmp.dropLast()) : tmp) + "/instantllm-\(getuid()).sock"
}

/// First existing path among: explicit option, environment variable, next to the binary,
/// ~/Library/Application Support/instantllm, ./models/ill.
/// Finds an asset: explicit path, environment variable, then next to the executable, its
/// ../share/instantllm, ~/Library/Application Support/instantllm, the source tree the executable
/// was built in (<repo>/.build/<triple>/release -> <repo>/models/ill), and models/ill.
func resolveAsset(_ explicit: String?, env: String, name: String) -> String {
    if let e = explicit { return e }
    if let v = ProcessInfo.processInfo.environment[env], !v.isEmpty { return v }
    let exeURL = Bundle.main.executableURL ?? URL(fileURLWithPath: CommandLine.arguments[0])
    let exe = exeURL.resolvingSymlinksInPath().deletingLastPathComponent().path
    let home = FileManager.default.homeDirectoryForCurrentUser.path
    for dir in [exe, exe + "/../share/instantllm", home + "/Library/Application Support/instantllm", exe + "/../../../models/ill", "models/ill"] {
        let p = dir + "/" + name
        if FileManager.default.fileExists(atPath: p) { return p }
    }
    return "models/ill/" + name
}

/// The system prompt of the benchmark (bench/system.txt); a system.txt asset or INSTANTLLM_SYSTEM
/// (a file path) overrides it.
let builtinSystemPrompt = "You are a command-line assistant on macOS (zsh). Reply with a single shell command that does what the user asks. Output only the command: no explanation, no markdown."
func defaultSystemPrompt(_ explicitFile: String? = nil) -> String {
    (try? String(contentsOfFile: resolveAsset(explicitFile, env: "INSTANTLLM_SYSTEM", name: "system.txt"), encoding: .utf8)) ?? builtinSystemPrompt
}

private func readAll(_ fd: Int32, _ p: UnsafeMutableRawPointer, _ n: Int) -> Bool {
    var got = 0
    while got < n {
        let r = read(fd, p + got, n - got)
        if r < 0 && errno == EINTR { continue }
        if r <= 0 { return false }
        got += r
    }
    return true
}

private func writeAll(_ fd: Int32, _ p: UnsafeRawPointer, _ n: Int) -> Bool {
    var off = 0
    while off < n {
        let w = write(fd, p + off, n - off)
        if w < 0 && errno == EINTR { continue }
        if w <= 0 { return false }
        off += w
    }
    return true
}

func serve(args: Args) -> Never {
    if args.flags.contains("detach") {
        setsid()
        let null = open("/dev/null", O_RDWR)
        dup2(null, 0); dup2(null, 1); dup2(null, 2)
    }
    signal(SIGPIPE, SIG_IGN)
    // Opt out of App Nap / timer coalescing and run at interactive QoS: an idle daemon otherwise
    // wakes slowly and its GPU work is scheduled as background work.
    let activity = ProcessInfo.processInfo.beginActivity(options: [.userInitiatedAllowingIdleSystemSleep, .latencyCritical],
                                                         reason: "instantllm daemon answers interactive requests")
    _ = activity
    pthread_set_qos_class_self_np(QOS_CLASS_USER_INTERACTIVE, 0)
    let verbose = args.flags.contains("verbose")
    let path = args.options["socket"] ?? socketPath()
    let idleExit = Double(args.int("idle-exit", 900))
    let defaultSystem = defaultSystemPrompt(args.options["system-file"])
    let tok: Tokenizer
    let engine: Engine
    do {
        tok = try Tokenizer(path: resolveAsset(args.options["tokenizer"], env: "INSTANTLLM_TOKENIZER", name: "qwen.tkn"))
        engine = try Engine(modelPath: resolveAsset(args.options["model"], env: "INSTANTLLM_MODEL", name: "qwen-q4.ill"),
                            copyWeights: !args.flags.contains("mmap"))
    } catch { fail("serve: \(error)") }

    engine.specT = args.int("spec", engine.defaultSpecT)
    if engine.specT > 1 && (try? engine.loadDraftTable(path: resolveAsset(args.options["draft-table"], env: "INSTANTLLM_DRAFT", name: "ngram.bin"))) == nil { engine.specT = 1 }
    if !args.flags.contains("no-ildraft") {
        try? engine.loadLearnedDrafter(path: resolveAsset(args.options["ildraft"], env: "INSTANTLLM_ILDRAFT", name: "ildraft.bin"))
    }
    // Warm everything once: pipelines, the system prefix in the KV cache, page-ins.
    _ = engine.generate(tok.encodeChat(system: defaultSystem, user: "list files"), maxNew: 4)

    let fd = socket(AF_UNIX, SOCK_STREAM, 0)
    var addr = sockaddr_un()
    addr.sun_family = sa_family_t(AF_UNIX)
    _ = withUnsafeMutableBytes(of: &addr.sun_path) { raw in
        path.withCString { strncpy(raw.baseAddress!.assumingMemoryBound(to: CChar.self), $0, raw.count - 1) }
    }
    unlink(path)
    let len = socklen_t(MemoryLayout<sockaddr_un>.size)
    guard withUnsafePointer(to: &addr, { $0.withMemoryRebound(to: sockaddr.self, capacity: 1) { bind(fd, $0, len) } }) == 0,
          listen(fd, 16) == 0 else { fail("serve: cannot listen on \(path)") }
    FileHandle.standardError.write("instantllm: serving on \(path)\n".data(using: .utf8)!)

    var buf = [UInt8](repeating: 0, count: 1 << 16)
    // While idle, a no-op dispatch every few seconds keeps the GPU out of deep sleep (waking from
    // it adds ~40 ms to the next request); after `idle-exit` seconds without requests, quit.
    let keepalive = Double(args.int("keepalive-ms", 2000)) / 1000
    // The GPU clock governor drops the clock within ~50 ms of idle and a ~20 ms request ends
    // before it ramps back (requests after a pause took ~2x as long). A 32-thread spin kernel on a
    // second queue keeps the GPU looking busy (measured cost < 1 W) for `heat-seconds` after the
    // last request; 0 disables it.
    let heatSeconds = Double(args.int("heat-seconds", 300))
    if heatSeconds > 0 { engine.startHeater() }
    var lastRequest = Date()
    while true {
        var pfd = pollfd(fd: fd, events: Int16(POLLIN), revents: 0)
        let pr = poll(&pfd, 1, Int32(keepalive * 1000))
        if pr == 0 {
            if Date().timeIntervalSince(lastRequest) > idleExit { unlink(path); exit(0) }
            if Date().timeIntervalSince(lastRequest) > heatSeconds { engine.stopHeater() }
            engine.wake()
            continue
        }
        if pr < 0 { continue }
        lastRequest = Date()
        let c = accept(fd, nil, nil)
        if c < 0 { continue }
        let tAccept = clock_gettime_nsec_np(CLOCK_UPTIME_RAW)
        engine.wake()
        if heatSeconds > 0 { engine.startHeater() }
        var hdr = [UInt32](repeating: 0, count: 4)
        guard readAll(c, &hdr, 16), hdr[0] == 0x3151_4C49, Int(hdr[2]) + Int(hdr[3]) < buf.count else { close(c); continue }
        let sLen = Int(hdr[2]), pLen = Int(hdr[3])
        guard readAll(c, &buf, sLen + pLen) else { close(c); continue }
        let system = sLen > 0 ? String(decoding: buf[0..<sLen], as: UTF8.self) : defaultSystem
        let prompt = String(decoding: buf[sLen..<(sLen + pLen)], as: UTF8.self)
        let maxNew = max(1, min(Int(hdr[1]), engine.maxSteps))
        let ids = tok.encodeChat(system: system, user: prompt)
        if ids.count + maxNew >= engine.maxContext { close(c); continue }
        let prefixLen = tok.encodeWithSpecials("<|im_start|>system\n" + system + "<|im_end|>\n<|im_start|>user\n").count
        if ids.count >= prefixLen + 5 {
            engine.setDraftContext(prompt: Array(ids[prefixLen..<(ids.count - 5)]), text: prompt, encode: tok.encode)
        }
        engine.generate(ids, maxNew: maxNew) { t in
            let b = tok.tokenBytes(t)
            return b.count == 0 || writeAll(c, b.baseAddress!, b.count)
        }
        close(c)
        if verbose {
            let t = engine.lastTiming
            FileHandle.standardError.write(String(format: "request: accept->start %.2f ms, ttft %.2f ms, total %.2f ms, prefill %d\n",
                Double(t.tStart - tAccept) / 1e6, Double(t.tFirst - tAccept) / 1e6, Double(t.tEnd - tAccept) / 1e6, t.prefillTokens).data(using: .utf8)!)
        }
    }
}
